def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for index, operation in enumerate(ops):
        parts = operation.split(" ")
        verb = parts[0]

        if verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(index)
                continue

            action = history.pop()
            kind = action[0]

            if kind == "open":
                del balances[action[1]]
                frozen.discard(action[1])
            elif kind == "deposit":
                balances[action[1]] -= action[2]
            elif kind == "withdraw":
                balances[action[1]] += action[2]
            elif kind == "transfer":
                balances[action[1]] += action[3]
                balances[action[2]] -= action[3]
            elif kind == "freeze":
                frozen.remove(action[1])
            else:
                frozen.add(action[1])

        elif verb in ("freeze", "unfreeze") and len(parts) == 2:
            account = parts[1]
            if not account or account not in balances:
                rejected.append(index)
            elif verb == "freeze":
                if account in frozen:
                    rejected.append(index)
                else:
                    frozen.add(account)
                    history.append((verb, account))
            else:
                if account not in frozen:
                    rejected.append(index)
                else:
                    frozen.remove(account)
                    history.append((verb, account))

        elif verb in ("open", "deposit", "withdraw", "transfer"):
            expected = 4 if verb == "transfer" else 3
            if len(parts) != expected or any(not part for part in parts):
                rejected.append(index)
                continue

            amount_text = parts[-1]
            if any(char < "0" or char > "9" for char in amount_text):
                rejected.append(index)
                continue

            # Parse in small chunks to support amounts of arbitrary length.
            amount = 0
            for start in range(0, len(amount_text), 9):
                chunk = amount_text[start:start + 9]
                amount = amount * (10 ** len(chunk)) + int(chunk)

            account = parts[1]

            if verb == "open":
                if account in balances:
                    rejected.append(index)
                else:
                    balances[account] = amount
                    history.append((verb, account))

            elif verb == "deposit":
                if amount == 0 or account not in balances:
                    rejected.append(index)
                else:
                    balances[account] += amount
                    history.append((verb, account, amount))

            elif verb == "withdraw":
                if (amount == 0 or account not in balances
                        or account in frozen or balances[account] < amount):
                    rejected.append(index)
                else:
                    balances[account] -= amount
                    history.append((verb, account, amount))

            else:
                destination = parts[2]
                if (amount == 0 or account == destination
                        or account not in balances or destination not in balances
                        or account in frozen or balances[account] < amount):
                    rejected.append(index)
                else:
                    balances[account] -= amount
                    balances[destination] += amount
                    history.append((verb, account, destination, amount))

        else:
            rejected.append(index)

    return balances, rejected
